#!/bin/bash

# check and install msgpack-c 

filename="/tmp/test_msgpack.cc"
execfile="/tmp/test_msgpack"
tmpfile=$(mktemp ${filename})

content="
#include <msgpack.hpp>
#include <sstream>

int main(void)
{
    msgpack::type::tuple<int, bool> src(1, true);
    std::stringstream buffer;
    msgpack::pack(buffer, src);
    return 0;
}
"

echo "$content" > $filename
if g++ -o $execfile $filename; then 
    echo "msgpack installed";
else 
    git clone https://github.com/msgpack/msgpack-c.git
    cd msgpack-c
    cmake .
    make
    # sudo make install
    cd ..
    rm -rf msgpack-c  
fi

rm -rf "$execfile"
rm -rf "$tmpfile"

#!/bin/bash
CUR_DIR="."
TMP_DIR="./tmp"

declare -A DIR_MAP=( ["./test"]=1 ["./zmq_ops"]=1)

create_tmp() {
    if [ -d "$TMP_DIR" ]; then
        rm -rf $TMP_DIR
    else
        mkdir ${TMP_DIR}
    fi
}

format_files() {
    # echo "format dir $1"
    array=()
    while IFS=  read -r -d $'\0'; do
        array+=("$REPLY")
    done < <(find $1 -type f \( -iname \*.cc -o -name \*.h \) -print0)
    reg="^(.+\/)*(.*?)$"
    for file in ${array[@]};
    do
        if [[ $file =~ $reg ]]; then
            formated_file="$TMP_DIR/${BASH_REMATCH[2]}"
            echo "$file"
            clang-format -style=file $file > $formated_file
            cp $formated_file $file
        fi
    done
}

search_dir() {
    for dir in "$1"/*;
    do 
    if [ -d "$dir" ]; then 
        if [[ ! -z "${DIR_MAP[$dir]+unset}" ]]; then
            format_files "$dir"
            search_dir "$dir"
        fi
    fi
    done
}

del_tmp() {
    if [ -d "$TMP_DIR" ]; then
        rm -rf $TMP_DIR
    fi
}


create_tmp;
{
    search_dir "$CUR_DIR";
}
del_tmp

from tensorflow.python.framework import load_library
from tensorflow.python.platform import resource_loader

zmq_ops = load_library.load_op_library(
    resource_loader.get_path_to_datafile('nvzmq_ops.so'))
zmq_conn_handle = zmq_ops.zmq_conn_handle
zmq_op = zmq_ops.nv_zmq

'''
TODO: update when kernel changes.
'''
class ZmqOp(object):
    def __init__(self, address, zmq_hwm=0, zmq_buff=0):
        self._zmq_conn_handle = zmq_conn_handle(address, zmq_hwm, zmq_buff)
        self._address = address

    @property
    def address(self):
        return self._address

    def pull(self, types):
        return zmq_op(handle=self._zmq_conn_handle, types=types)
